import React from 'react';

export default function AboutSection() {
  return (
    <section className="max-w-5xl mx-auto px-4 py-8">
      <div className="bg-white rounded-xl shadow-md p-6">
        <h3 className="text-xl font-bold mb-4">What we are</h3>
        <p className="text-gray-700 text-sm">
          We are a close-knit Indian community based in Seychelles, united by heritage and strengthened by shared
          values. Rooted in our cultural traditions, we are committed to fostering education, promoting social welfare,
          and celebrating unity across generations. Our organization serves as a bridge between the past and the future
          empowering youth, honoring our elders, and creating platforms where every member can grow, contribute, and
          belong. Through events, educational initiatives, and community support, we aim to uphold the values that
          define us: respect, inclusiveness, and progress.
        </p>
      </div>
    </section>
  );
}
